import {projectPickerOptions,selectableProjects as projects} from './project-directory.mjs';
import {formatPresets,presetRules,ruleSummary,importFormatRules,exportFormatRules,suggestedFormatExclusions} from './format-presets.mjs';
import {createFormatReport,formatReportHtml} from './format-report.mjs';
import {mountToolJobPanel} from './tool-job-panel.mjs';
import {withStableView} from './view-stability.mjs';
import {toolBanner} from './tool-banner.mjs';
import {defaultRules,checkFormatting,validateRules,rulesFromTemplate,formatAdviceSnapshot} from './format-model.mjs';
import {keys,list,write,recordTask,hasDraftScope} from './state.mjs';
import {esc,icon,download} from './ui.mjs';
let root,ctx,item,doc,bytes,rules,checked=false,applied=null,dirty=false,busy=false,controller,view='original',tab='base',focus=0,formatStep=1,formatService='smart',templateChoice='custom';
let formatEpoch=0,autosaveTimer=null,verification=null,formatAI=null,formatScoped=false,formatDocumentPromise=null;
function loadFormatDocument(){return formatDocumentPromise||=import('./assets/format-document.js').catch(error=>{formatDocumentPromise=null;throw error;});}
export function disposeFormat(){if(dirty)saveFormat(true);clearTimeout(autosaveTimer);formatAI?.dispose();formatAI=null;formatEpoch++;controller?.abort();controller=null;root=null;dirty=false;busy=false;}
const $=s=>root?.querySelector(s),to64=b=>{let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.slice(i,i+8192));return btoa(s);},from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export const formatHasWork=()=>!!root?.querySelector('.format-space')&&(dirty||busy||!!root.querySelector('#format-ai-task:not([hidden])'));
export function formatRouteGuard(){if(!root?.querySelector('.format-space'))return true;if(busy){ctx.notify('文档处理中，请稍候。');return false;}if(dirty&&!saveFormat(true)){ctx.notify('排版草稿保存失败，请先下载原件。');return false;}return true;}
window.addEventListener('beforeunload',e=>{if(formatHasWork()){e.preventDefault();e.returnValue='';}});
export async function mountFormat(context,id,projectId){disposeFormat();formatScoped=hasDraftScope();const epoch=formatEpoch;controller=new AbortController();ctx=context;root=document.querySelector('.dashboard');const loaded=list(keys.drafts).find(d=>String(d.id)===String(id)&&d.tool==='format')||(!id?list(keys.drafts).filter(d=>d.tool==='format'&&d.formatting?.autoSession).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)))[0]:null)||{title:'毕业论文示例',projectId:projectId||'',example:true};item=loaded;const routeParams=new URLSearchParams(String(window.location.hash).split('?')[1]||'');formatService=normalizeFormatService(['check','smart','refine'].includes(routeParams.get('service'))?routeParams.get('service'):loaded.formatting?.service);templateChoice=formatPresets.some(preset=>preset.id===loaded.formatting?.template)?loaded.formatting.template:'custom';rules={...defaultRules(),...loaded.formatting?.rules};checked=loaded.formatting?.checked===true;applied=null;verification=null;dirty=false;busy=true;view='original';tab='base';focus=0;formatStep=loaded.formatting?.applied||formatService==='check'&&checked?4:Math.max(1,Math.min(3,Number(loaded.formatting?.step)||1));root.innerHTML=`<div class="format-space">${toolBanner('format',{extraClass:'detail-service-banner',description:'正在读取本地文档…'})}</div>`;try{const {parseDocx,applyDocx,exampleDocx}=await loadFormatDocument();if(epoch!==formatEpoch)return;const incoming=loaded.formatting?.original?from64(loaded.formatting.original):await exampleDocx();if(epoch!==formatEpoch)return;const parsed=await parseDocx(incoming);if(epoch!==formatEpoch)return;if(loaded.formatting?.levels)parsed.paragraphs.forEach((p,i)=>{const l=loaded.formatting.levels[i];if([0,1,2,3].includes(l))p.level=l;});if(loaded.formatting?.excluded)parsed.paragraphs.forEach((p,i)=>{p.excluded=loaded.formatting.excluded[i]===true;});let formatted=null;if(loaded.formatting?.applied){formatted=await applyDocx(incoming,parsed,rules);if(epoch!==formatEpoch)return;}bytes=incoming;doc=parsed;applied=formatted;if(id&&!loaded.formatting){ctx.notify('旧记录未包含原文文件，请重新上传 DOCX。原记录未被修改。');item={...loaded,title:loaded.title||'毕业论文示例',example:true};}if(formatted){const verified=await parseDocx(formatted);verified.paragraphs.forEach((p,i)=>{p.excluded=doc.paragraphs[i]?.excluded===true;});verification=checkFormatting(verified,rules);if(epoch!==formatEpoch)return;checked=true;view='formatted';}draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('change',changes,{signal:controller.signal});root.addEventListener('input',changes,{signal:controller.signal});}catch(e){if(epoch===formatEpoch)root.innerHTML=`<div class="format-space">${toolBanner('format',{extraClass:'detail-service-banner',description:'文档读取失败，请重新上传或使用示例。',actions:'<a class="btn secondary" href="#category/format">重新开始</a>'})}<p class="hub-error" role="alert">${esc(e.message)}</p></div>`;}finally{if(epoch===formatEpoch)busy=false;}}
function select(key,label,values){return `<label>${label}<select data-rule="${key}" aria-label="${label}">${values.map(([v,t])=>`<option value="${v}" ${String(rules[key])===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const sizes=[[10.5,'五号 · 10.5pt'],[12,'小四 · 12pt'],[14,'四号 · 14pt'],[16,'三号 · 16pt'],[18,'小二 · 18pt']];
const formatStages=[['template','选择模板','先确定学校或通用排版规则'],['upload','上传论文','导入需要排版的 DOCX 文件'],['format','自动排版','检查并应用排版设置'],['download','下载结果','导出排版后的 Word 文档']];
const formatFlows={
 check:{title:'格式检测',desc:'选择通用或自定义规则，上传 DOCX，检查实际格式差异。',steps:[['template','选择模板','选择通用或自定义格式规则'],['upload','上传论文','上传需要检测的 DOCX 文档'],['detect','自动检测','生成格式问题清单'],['report','检测报告','查看问题位置与修改建议']]},
 smart:{title:'智能排版',desc:'按通用或自定义规则，检查并生成排版副本，原件保留。',steps:[['template','选择模板','选择通用或自定义格式规则'],['upload','上传论文','上传需要排版的 DOCX 文档'],['format','自动排版','检查并应用排版设置'],['download','下载结果','导出排版后的 Word 文档']]},
};
const normalizeFormatService=value=>value==='check'?'check':'smart';
const currentFlow=()=>formatFlows[formatService]||formatFlows.smart;
const isExampleDocument=()=>item.example===true||(!item.fileName&&/示例/.test(item.title||''));
const formatServices=[['check','格式检测','检查字体、字号、行距和页边距，生成问题清单。','search'],['smart','智能排版','按选定规则生成排版副本，并提供预览。','spark']];
function formatServiceCards(){return `<section class="format-services" aria-label="格式排版服务"><div class="format-services-heading"><div><span class="format-flow-kicker">DOCUMENT FORMAT STUDIO</span><h2>规范的论文，从清晰的格式开始</h2><p>检查格式问题，按规则自动排版，原件与修改结果都可核对。</p></div><span class="hub-badge">本地处理 · 原件保留</span></div><div class="format-service-grid" role="group" aria-label="选择格式服务">${formatServices.map(([id,title,desc,ico])=>`<button type="button" class="format-service-card format-entry-${id} ${formatService===id?'active':''}" data-format-service="${id}" aria-pressed="${formatService===id}"><span class="format-service-icon">${formatServiceIcon(id,25)}</span><span class="format-service-copy"><span class="format-service-kicker">${id==='check'?'FORMAT CHECK':'SMART LAYOUT'}</span><strong>${title}</strong><small>${desc}</small><span class="format-service-delivery">${id==='check'?'交付：问题位置与格式清单':'交付：排版副本与修改清单'}</span></span>${formatService===id?'<b class="format-service-check">已选择</b>':icon('arrow',15)}</button>`).join('')}</div></section>`;}
function formatServiceIcon(service,size=24){const paths={check:'M14 3H5v18h14V8zM14 3v5h5M8 12h5M8 16h3M19 16l3 3M21 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',smart:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h8M8 18h4M2 7h1M2 11h1M2 15h1',refine:'M5 3h10l4 4v5M15 3v5h4M5 3v18h7M8 12h5M14 19l6-6 3 3-6 6h-3z'};return `<svg width="${size}" height="${size}" viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${paths[service]||paths.smart}"/></svg>`;}


const formatTemplateCards=formatPresets.map(preset=>[preset.name,preset.description]);
const currentRuleSummary=()=>{try{return ruleSummary(rules);}catch{return '规则尚未填写完整，请核对字号、行距和1–5cm页边距。';}};
const templateOptions=()=>formatPresets.map(preset=>`<option value="${preset.id}">${preset.name}</option>`).join('');
function formatModePanel(){if(formatStep!==1)return '';return `<section class="format-mode-panel"><div class="format-template-heading"><div><span class="format-flow-kicker">SELECT YOUR FORMAT</span><h2>选规则，再上传论文</h2><p>通用规则可直接调整；有学校规范时，使用自己的格式样例。以下均为PaperKnow通用规则。</p></div><label class="format-template-search">${icon('search',16)}<input id="format-school-search" placeholder="搜索通用规则或文稿类型" aria-label="搜索格式模板"></label></div><div class="format-template-grid">${formatTemplateCards.map(([title,desc],i)=>{const preset=formatPresets[i],value=preset.id,selected=templateChoice===value;return `<button type="button" class="format-template-card format-preset-${preset.accent} ${selected?'active':''}" data-template-choice="${i}" aria-pressed="${selected}"><span class="format-template-sheet" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span class="format-template-copy"><small>${preset.category}</small><strong>${title}</strong><small>${desc}</small><em>${selected?'当前规则 ✓':'使用此规则 →'}</em></span></button>`;}).join('')}</div><p id="format-template-empty" class="format-template-empty" hidden>没有匹配的通用模板。可使用自定义规则或导入你的DOCX格式样例；当前没有学校官方模板库。</p><div class="format-rule-import"><div class="format-sample-copy"><strong>使用学校或期刊的格式样例</strong><p>选择一种来源即可。自动读取 DOCX 中可识别的正文格式与页边距，再按实际要求核对。</p>${item.formatSample?`<small>已读取：${esc(item.formatSample.name)} · ${item.formatSample.imported.length} 项规则</small>`:''}</div><div class="format-sample-actions"><label class="btn secondary format-upload">${icon('upload',16)}上传 DOCX 样例<input id="format-sample-file" type="file" accept=".docx" aria-label="导入 DOCX 格式样例" data-file-library-label="从文件管理选择样例"></label></div></div><details id="format-rule-backup" class="format-rule-backup"><summary><span>${icon('folder',15)}恢复旧版规则</span><small>仅用于恢复已有备份</small><span class="format-backup-chevron" aria-hidden="true">⌄</span></summary><div class="format-backup-content"><p>导入此前导出的 PaperKnow 规则备份（JSON），或备份当前设置。学校提供的 Word 模板请使用上方的格式样例入口。</p><div class="format-backup-actions"><label class="btn secondary format-upload">${icon('upload',16)}导入规则备份<input id="format-rules-file" type="file" accept=".json,application/json" aria-label="导入排版规则JSON" data-file-library-label="从文件管理恢复规则"></label><button type="button" class="btn secondary" data-action="rules-export">${icon('download',16)}导出规则备份</button></div></div></details><p class="format-selected-rules">${esc(currentRuleSummary())}</p></section>`;}

function formatFlowPanel(){
 const [key,title,desc]=currentFlow().steps[formatStep-1]||currentFlow().steps[0];
 const action=formatStep===1?'next-step':formatStep===2?'next-step':formatStep===3?(formatService==='check'?'check':'apply'):(formatService==='check'?'report-html':'export');
 const actionLabel=formatStep===1?('确认规则，上传论文'):formatStep===2?(formatService==='check'?'核对规则，开始检测':'核对规则，准备排版'):formatStep===3?(formatService==='check'?'检查格式':applied?'重新应用排版':'检查并应用排版'):(formatService==='check'?'下载检测报告':'下载排版结果');
 const helper=formatStep===1?('选择通用模板或自定义规则，也可导入 DOCX 格式样例。'):formatStep===2?('仅支持 DOCX，文件在当前浏览器本地读取，不会上传到云端。'):formatStep===3?(formatService==='check'?'当前为格式检测：生成问题清单，不会修改原文件。':'先检查格式差异，再应用可修正项。原始文件始终保留，复杂对象请在 Word 中核对。'):formatService==='check'?'检测报告会展示问题位置与规则建议。':'排版副本已生成。下载后请在 Word 中检查分页、目录、表格、图片和公式。';

 return `<section class="card format-flow-card" aria-label="格式排版流程"><span class="format-flow-symbol" aria-hidden="true">${formatServiceIcon(formatService,27)}</span><div class="format-flow-copy"><span class="format-flow-kicker">STEP ${String(formatStep).padStart(2,'0')} · ${key.toUpperCase()}</span><h2>${title}</h2><p>${desc}</p><span class="format-flow-document-state">${isExampleDocument()?'示例文档体验 · 尚未导入你的论文':`当前原文：${esc(item.fileName||item.title+'.docx')}`}</span></div><div class="format-flow-summary"><span class="hub-badge ${formatStep===4?'mint':''}">${formatStep===4?(formatService==='check'?'检测结果已就绪':'排版副本已就绪'):`步骤 ${formatStep}/4`}</span><p>${helper}</p></div><div class="format-flow-actions">${formatStep>1?'<button class="btn secondary" data-action="prev-step">返回上一步</button>':''}<button class="btn primary" data-action="${action}" ${formatStep===3&&doc.blocked?'disabled':''}>${actionLabel} ${icon(formatStep===4?'download':'arrow',15)}</button></div>${formatStep===2?formatUploadPanel():''}${formatStep===4?formatDeliveryPanel():''}</section>`;
}

function draw(){formatAI?.dispose();formatAI=null;return withStableView(root,()=>{drawContents();mountFormatAI();});}function drawContents(){const issues=checked?checkFormatting(doc,rules):[],fix=issues.filter(i=>i.status==='fix').length,unknown=issues.length-fix;root.innerHTML=`<div class="format-space format-commercial doc-tool-detail doc-tool-format" data-format-mode="${formatService}" data-format-step="${formatStep}">${toolBanner('format',{extraClass:'detail-service-banner',description:'上传 DOCX，按规范检查与整理文档格式。',actions:`<a class="btn secondary" href="#assets?scope=local">排版记录</a><label class="btn primary format-upload">${icon('upload',17)}上传论文<input id="format-file" type="file" accept=".docx" aria-label="上传 DOCX 论文"></label>`})}<div class="format-steps">${currentFlow().steps.map(([id,label,desc],i)=>`<button type="button" class="format-step ${i+1===formatStep?'active':''} ${i+1<formatStep?'done':''}" data-step="${i+1}"  aria-current="${i+1===formatStep?'step':'false'}"><b>${i+1<formatStep?'✓':i+1}</b><span><strong>${label}</strong><small>${desc}</small></span></button>`).join('')}</div>${formatFlowPanel()}<div class="format-grid format-grid-step-${formatStep}"><section class="card format-settings doc-detail-panel"><div class="hub-card-heading"><h2>排版规范</h2><span class="hub-badge">${isExampleDocument()?'示例文档 · 请上传你的论文':'用户文档'}</span></div><div class="format-file">${icon('file',25)}<div><b>${esc(item.fileName||item.title+'.docx')}</b><small>${doc.paragraphs.length} 个正文段落 · ${doc.chars} 字符</small></div><button class="text-btn" data-action="original">下载原件</button></div><label class="research-field">成果名称<input id="format-title" aria-label="成果名称" maxlength="120" value="${esc(item.title)}"></label><label class="research-field">所属项目<select id="format-project" aria-label="所属项目" data-project-picker data-project-ref="${esc(item.projectId||'')}">${projectPickerOptions(item.projectId||'')}</select></label><label class="research-field">选择模板<select id="format-template" aria-label="选择模板">${templateOptions()}</select></label><p class="hub-footnote">通用规则并非学校或期刊官方模板，请核对实际要求。纸张与页眉页码保留原文件设置。</p><div class="research-tabs">${[['base','基础设置'],['heading','标题设置'],['scope','应用范围']].map(([v,t])=>`<button data-tab="${v}" class="${tab===v?'active':''}">${t}</button>`).join('')}</div><div class="format-rule-grid">${tab==='base'?`${select('font','正文字体',['宋体','黑体','仿宋','Times New Roman'].map(v=>[v,v]))}${select('size','正文字号',sizes)}${select('line','行距',[[1,'单倍'],[1.25,'1.25 倍'],[1.5,'1.5 倍'],[2,'2 倍']])}${select('indent','首行缩进',[[0,'无缩进'],[2,'2 字符']])}${['top','bottom','left','right'].map((k,i)=>`<label>${['上','下','左','右'][i]}页边距（cm）<input type="number" min="1" max="5" step="0.1" data-rule="${k}" aria-label="${['上','下','左','右'][i]}页边距" value="${esc(rules[k])}"></label>`).join('')}`:tab==='heading'?`${[1,2,3].map(n=>select('h'+n,n+' 级标题字号',sizes)).join('')}<p class="hub-footnote">标题统一黑体。依据原有大纲级别或“第一章”“1.1 标题”等文本识别，可在右侧手动校正。</p>`:`${[['body','正文样式'],['headings','标题字体与层级'],['margins','所有分节页边距']].map(([k,t])=>`<label class="research-check"><input type="checkbox" data-rule="${k}" ${rules[k]?'checked':''}>${t}</label>`).join('')}<p class="hub-footnote">仅处理正文顶层段落。表格内部、页眉页脚、批注与公式不自动排版。</p>`}</div>${doc.sections.length>1?`<label class="research-check format-section-consent"><input id="format-sections-confirm" type="checkbox" ${item.marginScopeConfirmed?'checked':''}>此文档有${doc.sections.length}个分节，我已核对横向页面，同意所选页边距应用至全部分节。</label>`:''}<p class="format-scope-note">已将${doc.paragraphs.filter(p=>p.excluded).length}段设为保留原样。封面、摘要、目录、参考文献等范围根据标题建议识别，请核对每段类型；所有段落均可手动调整。</p><div class="research-actions"><button class="btn secondary" data-action="check">检查格式</button>${formatService!=='check'?`<button class="btn primary" data-action="apply" ${doc.blocked?'disabled':''}>应用选定修改</button>`:''}</div><p id="format-status" class="hub-footnote" role="status">${dirty?'有未保存修改。':applied?'已生成并复查排版副本，可导出 Word。':'原始文件保留，应用前请核对范围。'}</p><button class="btn secondary" data-action="example">使用示例</button><div class="format-warnings">${doc.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}<p>连续预览仅展示正文文本；图片、表格、公式及真实分页请在 Word 中核对。</p></div></section><div class="format-review-column"><section class="card format-preview doc-detail-panel"><div class="hub-card-heading"><h2>文档预览</h2><small>连续预览 · 非 Word 分页</small></div><div class="format-preview-toolbar"><div class="research-tabs">${[['original','原始文档'],['formatted','排版预览']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}" ${v==='formatted'&&!applied?'disabled':''}>${t}</button>`).join('')}</div><label>定位段落<select id="format-focus" aria-label="定位段落">${doc.paragraphs.map((p,i)=>`<option value="${i}" ${focus===i?'selected':''}>${i+1}. ${esc(p.text.slice(0,18))}</option>`).join('')}</select></label></div><div class="format-paper-wrap" data-scroll-key="format-paper-wrap-1">${previewPagination()}<article class="format-paper" style="padding:${previewMargins()}">${previewParagraphs()}</article></div></section><section class="card format-results doc-detail-panel"><div class="hub-card-heading"><h2>格式检查结果</h2><span class="hub-badge">${checked?`${fix} 项可修正 · ${unknown} 项待确认`:'尚未检查'}</span></div>${checked?`<p class="hub-footnote">${applied?'原件检查结果保留，修改清单可供对照。':'检查原件与当前规则；不能确定的格式不会当作已验证合格。'}</p><div class="format-issues" data-scroll-key="format-issues-1">${issues.map((issue,i)=>`<div class="format-issue"><div><b>${issue.index!=null?'段落 '+(issue.index+1):'分节 '+(issue.section+1)} · ${issue.label}</b><p>${esc(issue.current)} → ${esc(issue.target)}</p></div><span class="hub-badge ${issue.status==='unknown'?'gray':''}">${issue.status==='unknown'?'需确认':'可修正'}</span>${issue.index!=null?`<button class="text-btn" data-locate="${issue.index}">查看位置</button>`:''}</div>`).join('')||'<p class="hub-footnote">当前检查范围内未发现差异。复杂对象不在自动检查范围内。</p>'}</div>`:`<div class="research-empty format-check-empty"><span aria-hidden="true">${formatServiceIcon('check',34)}</span><h3>格式问题，会在这里清晰呈现</h3><p>核对规则后点击“检查格式”，查看实际问题的位置与修改建议。</p><small>当前还没有生成检测结果，不代表格式已经合格。</small></div>`}</section>${formatAdviceCard()}${applied&&verification?`<div class="format-verification" role="status"><strong>排版副本已复查</strong><span>${verification.length?`仍有 ${verification.length} 项需要核对`:'所选规则检查未发现差异'} · 图片、表格、目录及真实分页请在 Word 中核对。</span></div>`:''}<div class="format-footer"><span>原始文件保留 · 修改可核对</span><div class="research-actions"><button class="btn secondary" data-action="report-html" ${!checked?'disabled':''}>下载可读格式报告</button>${formatService==='check'?`<button class="btn secondary" data-action="report-export" ${!checked?'disabled':''}>导出检测清单</button>`:`<button class="btn secondary" data-action="log" ${!applied?'disabled':''}>修改清单</button>`}<button class="btn secondary" data-action="save">保存记录</button>${formatService!=='check'?`<button class="btn primary" data-action="export" ${!applied?'disabled':''}>导出排版 Word</button>`:''}</div></div></div></div><p class="hub-footnote">排版在本地完成；选择 AI 解读时，仅提交上方说明的规则与检查节选，不上传 DOCX 原件。DOCX 最大 2MB；保存包括原件，浏览器空间不足时请先下载文件。目录、参考文献规范与页码不会自动重建。</p></div>`;bindDrop();}
function requireDocument(){if(isExampleDocument()&&!item.exampleConfirmed&&!item.formatting?.applied){ctx.notify('请先上传你的DOCX论文；也可以点击“体验示例文档”主动试用。');return false;}return true;}
function formatUploadPanel(){return `<div class="format-source-panel"><label class="format-source-drop format-upload">${icon('upload',35)}<strong>上传需要处理的论文</strong><span>选择DOCX文件 · 最大2MB · 浏览器本地处理</span><input id="format-file-flow" type="file" accept=".docx" aria-label="上传 DOCX 论文"></label><div class="format-source-state">${isExampleDocument()?`<strong>还没有上传你的论文</strong><p>原件会保留，先预览、核对规则，再下载排版副本。</p><button type="button" class="btn secondary" data-action="example">体验示例文档</button>`:`<strong>已导入：${esc(item.fileName||item.title+'.docx')}</strong><p>${doc.paragraphs.length}个顶层段落 · ${doc.chars}字符</p><span>可继续核对规则与段落范围。</span>`}</div></div>`;}
function formatDeliveryPanel(){const report=createFormatReport({item,document:doc,rules,verification,service:formatService}),summary=report.summary;return `<div class="format-delivery-panel"><div><strong>${formatService==='check'?'格式检测已完成':'排版副本已生成'}</strong><p>${esc(item.fileName||item.title+'.docx')}${isExampleDocument()?' · 示例体验':''}</p></div><div class="format-delivery-stats"><span><b>${summary.paragraphs}</b>原文段落</span><span><b>${summary.excludedParagraphs}</b>保留原样</span><span><b>${summary.originalIssues}</b>原件格式差异</span><span><b>${summary.outputVerified?summary.remainingIssues:'—'}</b>副本剩余差异</span></div><div class="research-actions"><button class="btn secondary" data-action="report-html">下载格式报告</button>${applied?'<button class="btn primary" data-action="export">下载排版Word</button>':''}<button class="btn secondary" data-action="original">下载原件</button></div></div>`;}
function previewParagraphs(){const start=Math.floor(focus/80)*80;return doc.paragraphs.slice(start,start+80).map((p,index)=>paragraph(p,start+index)).join('');}
function previewPagination(){if(doc.paragraphs.length<=80)return '';const start=Math.floor(focus/80)*80;return `<nav class="format-preview-pages" aria-label="文档段落分页"><button class="btn secondary" data-action="preview-prev" ${start===0?'disabled':''}>上一组</button><span>预览段落 ${start+1}–${Math.min(start+80,doc.paragraphs.length)} / ${doc.paragraphs.length}</span><button class="btn secondary" data-action="preview-next" ${start+80>=doc.paragraphs.length?'disabled':''}>下一组</button></nav>`;}
async function readRuleFile(file){if(!file||busy)return;const epoch=formatEpoch;if(file.size>16000||!/\.json$/i.test(file.name))return ctx.notify('请选择16KB以内的PaperKnow规则JSON。');busy=true;freeze(true);try{const text=await file.text();if(epoch!==formatEpoch)return;const next=importFormatRules(text);rules=next;templateChoice='custom';invalidate();draw();ctx.notify('排版规则已导入，请核对后应用。');}catch(error){if(epoch===formatEpoch)ctx.notify(error.message||'规则导入未完成。');}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}}
function previewMargins(){const m=view==='formatted'&&applied&&rules.margins?rules:doc.sections[0]||{};return ['top','right','bottom','left'].map(k=>Math.max(12,Number(m[k]||2.5)*14)+'px').join(' ');}
function paragraph(p,i){const f=p.format,formatted=view==='formatted'&&applied,head=p.level>0,selected=formatted&&!p.excluded&&(head?rules.headings:rules.body),font=selected?(head?'黑体':rules.font):f.font?.[0]||'宋体',size=selected?Number(head?rules['h'+Math.min(p.level,3)]:rules.size):f.size?.[0]||12,line=selected&&!head?rules.line:f.line?.[0]||1.5,indent=selected&&!head?rules.indent:f.indent?.[0]||0;return `<section id="format-p-${i}" class="format-paragraph ${focus===i?'focused':''} ${p.excluded?'format-excluded':''}"><p style="font-family:${esc(/^[\p{L}\p{N} -]{1,60}$/u.test(font)?font:'宋体')};font-size:${Math.max(6,Math.min(36,Number(size)||12))}pt;line-height:${Math.max(1,Math.min(3,Number(line)||1.5))};text-indent:${Math.max(0,Math.min(5,Number(indent)||0))}em">${esc(p.text)}</p><label class="format-role">段落 ${i+1}<select data-level="${i}" aria-label="段落 ${i+1} 类型"><option value="keep" ${p.excluded?'selected':''}>保留原样 · 不排版</option>${[[0,'正文'],[1,'一级标题'],[2,'二级标题'],[3,'三级标题']].map(([v,t])=>`<option value="${v}" ${!p.excluded&&p.level===v?'selected':''}>${t}</option>`).join('')}</select></label></section>`;}
function queueSave(){dirty=true;clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>saveFormat(true),550);}
function invalidate(){checked=false;applied=null;verification=null;view='original';queueSave();}
function changes(e){if(e.target.id==='format-focus')return changeContents(e);return withStableView(root,()=>{const result=changeContents(e);if(e.target.dataset.rule||e.target.dataset.level||['format-title','format-template'].includes(e.target.id))formatAI?.inputChanged?.();return result;});}function changeContents(e){const t=e.target;if(e.type==='input'&&['format-file','format-template'].includes(t.id))return;if(t.id==='format-file'||t.id==='format-file-flow'){readFile(t.files[0]);return;}if(t.dataset.rule){templateChoice='custom';root.querySelectorAll('#format-template').forEach(select=>select.value='custom');rules[t.dataset.rule]=t.type==='checkbox'?t.checked:t.tagName==='SELECT'&&t.dataset.rule==='font'?t.value:Number(t.value);invalidate();root.querySelectorAll('[data-template-choice]').forEach(button=>{const active=formatPresets[Number(button.dataset.templateChoice)]?.id==='custom';button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});try{const summary=$('.format-selected-rules');if(summary)summary.textContent=ruleSummary(rules);}catch{}$('#format-status').textContent='规则已修改，请重新检查并应用。';root.querySelectorAll('[data-action="export"],[data-action="log"]').forEach(button=>button.disabled=true);if(root.querySelector('[data-view="formatted"]'))root.querySelector('[data-view="formatted"]').disabled=true;root.querySelector('.format-paper').style.padding=previewMargins();root.querySelector('.format-paper').innerHTML=previewParagraphs();root.querySelector('[data-view="original"]').classList.add('active');root.querySelector('[data-view="formatted"]').classList.remove('active');root.querySelectorAll('[data-action="report-html"],[data-action="report-export"]').forEach(button=>button.disabled=true);root.querySelector('.format-results').innerHTML='<h2>格式检查结果</h2><p class="hub-footnote">规则已改变，请重新检查。</p>';}else if(t.id==='format-template'){setTemplate(t.value);}else if(t.id==='format-sections-confirm'){item.marginScopeConfirmed=t.checked;queueSave();}else if(t.id==='format-rules-file'){readRuleFile(t.files[0]);}else if(t.id==='format-advice-text'){item.formatAdvice.text=t.value;queueSave();}else if(t.id==='format-project'){item.projectId=t.value;queueSave();}else if(t.id==='format-title'){item.title=t.value;queueSave();}else if(t.dataset.level){const paragraph=doc.paragraphs[Number(t.dataset.level)];paragraph.excluded=t.value==='keep';if(t.value!=='keep')paragraph.level=Number(t.value);invalidate();draw();}else if(t.id==='format-focus'){focus=Number(t.value);locate();}}
function setTemplate(value){if(value==='custom'){templateChoice='custom';queueSave();draw();return;}if(!confirm('替换当前排版规则？')){root.querySelectorAll('#format-template').forEach(select=>select.value=templateChoice);return;}templateChoice=value;rules=presetRules(value,rules);invalidate();draw();}
function locate(){if(!$('#format-p-'+focus))draw();const target=$('#format-p-'+focus);root.querySelectorAll('.format-paragraph').forEach(p=>p.classList.toggle('focused',p===target));target?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function freeze(value){root.querySelectorAll('button,input,select').forEach(e=>{if(value){e.dataset.previousDisabled=String(e.disabled);e.disabled=true;}else if(e.dataset.previousDisabled!=null){e.disabled=e.dataset.previousDisabled==='true';delete e.dataset.previousDisabled;}});}
async function readFile(file){const epoch=formatEpoch;if(!file||busy)return;if(!/\.docx$/i.test(file.name)||file.size>2*1024*1024)return ctx.notify('请选择 2MB 以内的 DOCX 文件；PDF 不支持原样排版。');busy=true;freeze(true);try{const {parseDocx}=await loadFormatDocument();if(epoch!==formatEpoch)return;const next=new Uint8Array(await file.arrayBuffer());if(epoch!==formatEpoch)return;const parsed=await parseDocx(next);if(epoch!==formatEpoch)return;for(const match of suggestedFormatExclusions(parsed.paragraphs))parsed.paragraphs[match.index].excluded=true;if(dirty&&!saveFormat(true))throw new Error('当前文档尚未保存，请先下载备份。');bytes=next;doc=parsed;item={title:file.name.replace(/\.docx$/i,'').slice(0,120),fileName:file.name,projectId:item.projectId||'',formatSample:item.formatSample,example:false};invalidate();focus=0;formatStep=3;draw();ctx.notify('已读取你的DOCX原件，请核对规则、段落范围和预览后应用。');}catch(e){if(epoch===formatEpoch)ctx.notify(e.message||'读取失败，原文档未替换。');}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}}
function bindDrop(){const profile=currentFlow();const steps=root.querySelector('.format-steps');if(steps&&!root.querySelector('.format-services'))steps.insertAdjacentHTML('beforebegin',formatServiceCards());if(steps&&!root.querySelector('.format-mode-panel,.format-refine-panel'))steps.insertAdjacentHTML('afterend',formatModePanel());root.querySelectorAll('.format-step').forEach((step,i)=>{const data=profile.steps[i];if(!data)return;step.querySelector('strong').textContent=data[1];step.querySelector('small').textContent=data[2];});const pageHeading=root.querySelector('.hub-heading h1');const pageDesc=root.querySelector('.hub-heading p');if(pageHeading)pageHeading.textContent='格式排版';if(pageDesc)pageDesc.textContent=profile.desc;root.querySelector('#format-sample-file')?.addEventListener('change',e=>readFormatSample(e.target.files[0]));root.querySelectorAll('[data-format-service]').forEach(button=>button.addEventListener('click',()=>{const nextService=normalizeFormatService(button.dataset.formatService);if(formatService===nextService)return;formatService=nextService;formatStep=1;checked=false;applied=null;verification=null;view='original';queueSave();draw();}));root.querySelectorAll('[data-template-choice]').forEach(button=>button.addEventListener('click',()=>setTemplate(formatPresets[Number(button.dataset.templateChoice)]?.id||'custom')));root.querySelectorAll('#format-template').forEach(select=>select.value=templateChoice);const search=root.querySelector('#format-school-search');search?.addEventListener('input',()=>withStableView(root,()=>{const query=search.value.trim().toLowerCase();const cards=[...root.querySelectorAll('[data-template-choice]')];cards.forEach(card=>{card.hidden=!!query&&!card.textContent.toLowerCase().includes(query);});const empty=root.querySelector('#format-template-empty');if(empty)empty.hidden=cards.some(card=>!card.hidden);}));root.querySelector('[data-action="report"]')?.addEventListener('click',()=>{checked=true;draw();ctx.notify('格式检测报告已生成，请查看下方问题清单。');});root.querySelectorAll('.format-file,.format-source-drop').forEach(zone=>{zone.addEventListener('dragover',e=>e.preventDefault());zone.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length===1)readFile(e.dataTransfer.files[0]);else ctx.notify('每次请选择一个文件。');});});}
function changeLog(){return {title:item.title,example:item.example,rules,scope:'正文顶层段落及选择的分节页边距',paragraphs:doc.paragraphs.flatMap((p,index)=>!p.excluded&&(p.level?rules.headings:rules.body)?[{paragraph:index+1,type:p.level?'标题 '+p.level:'正文'}]:[]),originalIssues:checkFormatting(doc,rules),warnings:doc.warnings,note:'未自动修改表格、公式、图片、页眉页脚、批注或目录。'};}
async function actions(e){const epoch=formatEpoch;const b=e.target.closest('button');if(!b||busy)return;try{if(b.dataset.step){const n=Number(b.dataset.step);if(n>=3&&!requireDocument())return;if(n===4&&!(formatService==='check'?checked:applied)){ctx.notify('请先完成检测或生成排版副本，再查看结果。');return;}if(n<=formatStep||n===formatStep+1){formatStep=n;queueSave();draw();}return;}if(b.dataset.tab){tab=b.dataset.tab;draw();return;}if(b.dataset.view){view=b.dataset.view;draw();return;}if(b.dataset.locate!=null){focus=Number(b.dataset.locate);locate();return;}switch(b.dataset.action){case 'rules-export':await download('PaperKnow-排版规则.json',exportFormatRules(rules),'application/json');break;case 'report-html':if(!checked)throw Error('请先检查格式。');await download(item.title+'-格式报告.html',formatReportHtml(createFormatReport({item,document:doc,rules,verification,service:formatService})),'text/html;charset=utf-8');break;case 'preview-prev':focus=Math.max(0,Math.floor(focus/80)*80-80);draw();break;case 'preview-next':focus=Math.min(doc.paragraphs.length-1,Math.floor(focus/80)*80+80);draw();break;case 'format-ai':if(formatScoped)throw Error('账户草稿仅在内存编辑，请在独立格式排版页生成建议后保存到账户。');if(!checked)throw Error('请先完成格式检测，再解读当前问题清单。');await formatAI.generate();break;case 'advice-export':if(!item.formatAdvice)throw Error('请先生成并采纳格式建议。');await download(item.title+'-格式建议.txt','格式问题解读 · '+(item.formatAdvice.scope?.title||item.title)+'\n'+formatAdviceScope(item.formatAdvice)+'\n'+(formatAdviceStale(item.formatAdvice)?'注意：当前规则或资料已变化，以下为历史建议。\n':'')+'生成时间：'+(item.formatAdvice.createdAt||'未记录')+'\n\n'+item.formatAdvice.text+'\n\n'+item.formatAdvice.suggestions.map(s=>s.location+'：'+s.issue+'\n建议：'+s.action).join('\n\n'));break;case 'next-step':if(formatStep===1){formatStep=2;queueSave();draw();}else if(formatStep===2){if(!requireDocument())return;formatStep=3;queueSave();draw();}break;case 'prev-step':if(formatStep>1){formatStep-=1;queueSave();draw();}break;case 'check':if(!requireDocument())return;validateRules(rules);checked=true;if(formatService==='check')formatStep=4;queueSave();draw();break;case 'report-export':if(!checked)throw new Error('请先检查格式。');await download(item.title+'-格式检测清单.json',JSON.stringify({title:item.title,example:!!item.example,scope:'正文顶层段落及选择的分节页边距',rules,issues:checkFormatting(doc,rules),warnings:doc.warnings,note:'仅核对本地规则，不代表学校或期刊已审核合格。'},null,2),'application/json');break;case 'apply':if(!requireDocument())return;if(formatService==='check')throw new Error('请切换到智能排版后应用修改。');if(doc.sections.length>1&&rules.margins&&!item.marginScopeConfirmed)throw Error('文档包含多个分节，请先确认统一页边距，或关闭“所有分节页边距”。');validateRules(rules);busy=true;freeze(true);try{const {applyDocx,parseDocx}=await loadFormatDocument();if(epoch!==formatEpoch)return;const output=await applyDocx(bytes,doc,rules);if(epoch!==formatEpoch)return;const verified=await parseDocx(output);if(epoch!==formatEpoch)return;verified.paragraphs.forEach((p,i)=>{p.excluded=doc.paragraphs[i]?.excluded===true;});verification=checkFormatting(verified,rules);applied=output;checked=true;queueSave();view='formatted';formatStep=4;draw();ctx.notify('已生成排版副本，原文件未修改。');}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}break;case 'original':await download(item.fileName||item.title+'-原件.docx',bytes,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');break;case 'export':if(!applied)throw new Error('请先应用修改。');await download(item.title+'-排版.docx',applied,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');ctx.notify('已导出 DOCX，请在 Word 中核对最终分页。');break;case 'log':await download(item.title+'-修改清单.json',JSON.stringify(changeLog(),null,2),'application/json');break;case 'save':saveFormat();break;case 'example':if(dirty&&!confirm('放弃未保存修改并打开示例？'))return;busy=true;freeze(true);try{const {exampleDocx,parseDocx}=await loadFormatDocument();if(epoch!==formatEpoch)return;const nextBytes=await exampleDocx();if(epoch!==formatEpoch)return;const nextDoc=await parseDocx(nextBytes);if(epoch!==formatEpoch)return;bytes=nextBytes;doc=nextDoc;item={title:'毕业论文示例',example:true,projectId:''};rules=defaultRules();templateChoice='custom';checked=false;applied=null;dirty=false;view='original';formatStep=2;focus=0;item.exampleConfirmed=true;queueSave();draw();}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}break;}}catch(err){if(epoch===formatEpoch)ctx.notify(err.message||'操作失败，请先下载文件。');}}

function saveFormat(quiet=false){
 if(!item||!bytes||!doc||!root||formatScoped!==hasDraftScope())return false;
 try{if(!quiet)validateRules(rules);const all=list(keys.drafts),old=all.find(d=>d.id===item.id),now=new Date().toISOString();
 const next={...item,id:item.id||crypto.randomUUID(),title:item.title.trim()||'未命名排版草稿',tool:'format',stage:applied?'formatted':'draft',text:doc.paragraphs.map(p=>p.text).join('\n\n'),createdAt:old?.createdAt||now,updatedAt:now,formatting:{original:to64(bytes),rules:{...rules},step:formatStep,service:formatService,template:templateChoice,checked,applied:formatService!=='check'&&!!applied,levels:doc.paragraphs.map(p=>p.level),excluded:doc.paragraphs.map(p=>p.excluded===true),autoSession:true}};
 write(keys.drafts,old?all.map(d=>d.id===next.id?next:d):[next,...all]);item=next;dirty=false;
 if(!quiet){try{recordTask({id:'draft-'+item.id,title:item.title,kind:'排版记录保存',status:'completed',projectId:item.projectId,url:'#draft/'+item.id});}catch{}draw();ctx.notify(formatScoped?'排版编辑已暂存本页，请点击上方“保存到账户”。':'排版记录与原件已保存到当前浏览器。');}else if($('#format-status'))$('#format-status').textContent=formatScoped?'排版编辑已暂存本页，请点击上方“保存到账户”。':'已自动保存到当前浏览器。';return true;
 }catch{if(!quiet)ctx.notify('浏览器空间不足，记录未保存，请先下载原件和排版文件。');return false;}
}
async function readFormatSample(file){const epoch=formatEpoch;if(!file||busy)return;if(!/\.docx$/i.test(file.name)||file.size>2*1024*1024)return ctx.notify('请选择 2MB 以内的 DOCX 格式样例。');busy=true;freeze(true);try{const {parseDocx}=await loadFormatDocument();if(epoch!==formatEpoch)return;const sampleBytes=new Uint8Array(await file.arrayBuffer());if(epoch!==formatEpoch)return;const sample=await parseDocx(sampleBytes);if(epoch!==formatEpoch)return;const result=rulesFromTemplate(sample,rules);rules=result.rules;templateChoice='custom';item.formatSample={name:file.name,imported:result.imported,unresolved:result.unresolved};invalidate();draw();ctx.notify(`已读取 ${result.imported.length} 项规则；无法识别的项目保留当前值，请逐项确认。`);}catch(e){if(epoch===formatEpoch)ctx.notify(e.message||'格式样例读取失败。');}finally{if(epoch===formatEpoch){busy=false;freeze(false);}}}

function formatAdviceStale(advice){try{return advice.contextKey!==JSON.stringify(formatAdviceSnapshot(item,doc,rules,formatService));}catch{return true;}}
function formatAdviceScope(advice){const scope=advice.scope;return (scope?`依据当次规则与 ${scope.selectedIssues} / ${scope.totalIssues} 项问题、前 ${scope.selectedParagraphs.length} / ${scope.totalParagraphs} 段正文节选（每段最多 400 字符）。`:'仅依据当次检查规则与正文节选；此历史建议未记录节选数量。')+'未审查全文、图片、表格、公式与真实分页；AI 未修改 DOCX，建议需要人工核对。';}
function formatAdviceCard(){
 const advice=item.formatAdvice,stale=advice?formatAdviceStale(advice):false;
 return `<section class="card format-ai-advice"><div class="hub-card-heading"><div><h2>AI 解读格式问题</h2><p class="hub-footnote">仅提交当前规则、最多 80 项问题和前 12 段各 400 字符的正文节选；不上传 DOCX 原件。</p></div><button class="btn secondary" data-action="format-ai" ${checked&&!formatScoped?'':'disabled'}>解读当前检查清单</button></div><div id="format-ai-task" hidden></div>${advice?`<div class="format-advice-result"><strong>${stale?'规则或资料已变化 · 以下为历史建议':'已采纳的格式建议'}</strong><p class="hub-footnote">${esc(formatAdviceScope(advice))}</p><label>建议说明<textarea id="format-advice-text" aria-label="格式建议说明" rows="6" maxlength="10000">${esc(advice.text)}</textarea></label>${advice.suggestions.map(s=>`<article><b>${esc(s.location)}</b><p>${esc(s.issue)}</p><p>建议：${esc(s.action)}</p></article>`).join('')}<button class="btn secondary" data-action="advice-export">导出格式建议</button></div>`:''}<p class="hub-footnote">生成前确认费用。建议需要核对；实际文档修改仍由上方的确定性排版执行，原件始终保留。</p></section>`;
}
function mountFormatAI(){const container=$('#format-ai-task');if(!container)return;if(formatScoped){container.hidden=false;container.innerHTML='<p class="hub-footnote">账户草稿仅在内存编辑，请使用上方“保存到账户”。AI 解读需要可恢复的任务标识，请在独立格式排版页生成后，再主动保存到账户。</p><a class="btn secondary" href="#category/format">打开格式排版</a>';return;}const epoch=formatEpoch;
 formatAI=mountToolJobPanel({container,ctx,kind:'format',operation:'format',initialState:item.formatAIJob||{},getProjectRef:()=>item.projectId||'',isCurrent:()=>epoch===formatEpoch&&!!root?.isConnected,getSnapshot:()=>{if(!checked)throw Error('请先完成当前格式检测。');return formatAdviceSnapshot(item,doc,rules,formatService);},onStateChange:state=>{item.formatAIJob=state;queueSave();if(!saveFormat(true))throw Error('任务标识未能保存，请释放浏览器空间后重试；尚未提交新的付费任务。');},onApply:(output,job)=>{
  if(typeof output?.text!=='string'||!Array.isArray(output.suggestions))throw Error('格式建议结构不完整，请重新读取任务结果。');
  const previous=item.formatAdvice,snapshot=formatAdviceSnapshot(item,doc,rules,formatService);item.formatAdvice={text:output.text,suggestions:structuredClone(output.suggestions),jobId:job.id,createdAt:new Date().toISOString(),scope:{title:item.title,...structuredClone(snapshot.context)},contextKey:JSON.stringify(snapshot)};queueSave();if(!saveFormat(true)){item.formatAdvice=previous;throw Error('建议暂未保存，请释放浏览器空间后再次采纳。');}draw();ctx.notify('格式建议已保存；原始 DOCX 未被 AI 修改。');
 }});
}
